INSERT INTO app_private.coaching_models (model_key,name_i18n,focus_i18n,limitation_i18n,source_title,source_url,source_kind,topic_tags,selection_comment_i18n,selection_caution_i18n,example_questions_i18n) VALUES
('tantric_intimacy_v1','{"en":"Tantric Intimacy · Consent & Desire","ru":"Тантрический коучинг · Желание и близость","es":"Coaching tántrico · Deseo e intimidad"}'::jsonb,'{"en":"Explore embodied awareness, desire, boundaries, consent and respectful intimate dialogue.","ru":"Исследовать телесное присутствие, желания, границы, согласие и уважительный диалог о близости.","es":"Explorar conciencia corporal, deseo, límites, consentimiento y diálogo íntimo respetuoso."}'::jsonb,'{"en":"An original educational exercise for adults (18+), not sex therapy, medical care, trauma treatment, a sexual technique or a way to persuade a partner. No physical exercises or explicit content.","ru":"Авторская образовательная практика для взрослых (18+), не секс-терапия, лечение травмы, инструкция к интимным действиям или способ убедить партнёра. Телесных практик нет.","es":"Ejercicio educativo original para adultos (18+); no es terapia sexual, tratamiento del trauma, técnica sexual ni método para convencer a la pareja. No hay ejercicios físicos."}'::jsonb,'Holistic House original educational adaptation; ethics reference: Somatica Institute Code of Ethics','https://www.somaticainstitute.com/code-of-ethics/','original',ARRAY['intimacy','desire','consent','boundaries','tantra','relationships']::text[],'{"en":"For adult questions about sexual desire, embodied comfort, consent, intimacy and respectful communication.","ru":"Для взрослых вопросов о сексуальном желании, телесном комфорте, согласии, близости и разговоре с партнёром.","es":"Para preguntas adultas sobre deseo sexual, comodidad corporal, consentimiento, intimidad y comunicación respetuosa."}'::jsonb,'{"en":"Not suitable for coercion, violence, abuse, acute trauma or persistent sexual pain/dysfunction: seek qualified human support. Every question may be skipped.","ru":"При принуждении, насилии, острой травме, сексуальной боли или стойких нарушениях нужна помощь квалифицированного специалиста. Любой вопрос можно пропустить.","es":"No es adecuado ante coerción, violencia, trauma agudo, dolor sexual o dificultades persistentes: busca apoyo profesional. Todas las preguntas son opcionales."}'::jsonb,'{"en":["How can I talk about sex and boundaries with my partner?","I would like to understand my sexual desires without pressure."],"ru":["Как говорить с партнёром о сексе и границах?","Хочу лучше понимать свои сексуальные желания без давления."],"es":["¿Cómo hablar de sexo y límites con mi pareja?","Quiero entender mis deseos sexuales sin presión."]}'::jsonb)
INSERT INTO app_private.coaching_schemes (scheme_key,model_key,name_i18n,result_i18n,style,estimated_minutes,topic_tags,step_keys,required_custom_plan,published) VALUES
('tantric_intimacy_reflective_v1','tantric_intimacy_v1','{"en":"8 gentle reflections · Intimacy","ru":"8 вопросов · Близость","es":"8 preguntas · Intimidad"}'::jsonb,'{"en":"Your own words for a desire, a boundary and a respectful next step (or pause).","ru":"Ваши слова о желании, границе и добровольном следующем шаге (или паузе).","es":"Tus palabras sobre un deseo, un límite y un paso respetuoso (o una pausa)."}'::jsonb,'reflective',20,ARRAY['intimacy','desire','consent','boundaries','tantra','relationships']::text[],ARRAY['intention','presence','desire','boundaries','consent','dialogue','step','review']::text[],false,true)
INSERT INTO app_private.coaching_answer_sets (answer_set_key,choices) VALUES
('tantric_intention_answers_v1','[{"id":"closeness","label":{"en":"Emotional closeness","ru":"Эмоциональная близость","es":"Cercanía emocional"}},{"id":"desire","label":{"en":"Desire and interest","ru":"Желание и интерес","es":"Deseo e interés"}},{"id":"communication","label":{"en":"Talking with a partner","ru":"Разговор с партнёром","es":"Hablar con mi pareja"}},{"id":"boundaries","label":{"en":"Consent and boundaries","ru":"Согласие и границы","es":"Consentimiento y límites"}},{"id":"body","label":{"en":"Feeling at ease in my body","ru":"Комфорт в своём теле","es":"Comodidad en mi cuerpo"}},{"id":"unsure","label":{"en":"I am still exploring","ru":"Пока разбираюсь","es":"Todavía lo estoy explorando"}}]'::jsonb),
('tantric_presence_answers_v1','[{"id":"ease","label":{"en":"I feel at ease","ru":"Чувствую лёгкость","es":"Siento comodidad"}},{"id":"calm","label":{"en":"I feel calm and present","ru":"Чувствую спокойствие и присутствие","es":"Siento calma y presencia"}},{"id":"tension","label":{"en":"I notice tension","ru":"Замечаю напряжение","es":"Noto tensión"}},{"id":"distance","label":{"en":"I feel distant or disconnected","ru":"Ощущаю отстранённость","es":"Siento distancia o desconexión"}},{"id":"mixed","label":{"en":"It changes","ru":"По-разному","es":"Depende del momento"}},{"id":"unsure","label":{"en":"I am not sure","ru":"Не уверен(а)","es":"No estoy seguro/a"}}]'::jsonb),
('tantric_desire_answers_v1','[{"id":"emotional","label":{"en":"A trusting conversation","ru":"Доверительный разговор","es":"Una conversación de confianza"}},{"id":"affection","label":{"en":"Gentle affection","ru":"Нежность","es":"Afecto suave"}},{"id":"sensual","label":{"en":"Sensual connection","ru":"Чувственный контакт","es":"Conexión sensual"}},{"id":"space","label":{"en":"More personal space","ru":"Больше личного пространства","es":"Más espacio personal"}},{"id":"exploration","label":{"en":"Exploring preferences together","ru":"Вместе исследовать предпочтения","es":"Explorar preferencias juntos"}},{"id":"unsure","label":{"en":"I don''t know yet","ru":"Пока не знаю","es":"Aún no lo sé"}}]'::jsonb),
('tantric_boundaries_answers_v1','[{"id":"ask_first","label":{"en":"Ask before getting closer","ru":"Сначала спрашивать","es":"Preguntar antes de acercarse"}},{"id":"slower","label":{"en":"A slower pace","ru":"Более медленный темп","es":"Un ritmo más lento"}},{"id":"pause","label":{"en":"Freedom to pause anytime","ru":"Право остановиться в любой момент","es":"Poder pausar en cualquier momento"}},{"id":"privacy","label":{"en":"More privacy","ru":"Больше приватности","es":"Más privacidad"}},{"id":"no_pressure","label":{"en":"No expectations or pressure","ru":"Никакого давления и ожиданий","es":"Sin expectativas ni presión"}},{"id":"unsure","label":{"en":"I need time to understand","ru":"Мне нужно время разобраться","es":"Necesito tiempo para entenderlo"}}]'::jsonb),
('tantric_consent_answers_v1','[{"id":"direct","label":{"en":"Ask directly: ''Is this okay?''","ru":"Прямо спросить: «Тебе подходит?»","es":"Preguntar directamente: «¿Te parece bien?»"}},{"id":"check_in","label":{"en":"Check in as things change","ru":"Уточнять по ходу общения","es":"Consultar cuando cambie la situación"}},{"id":"no","label":{"en":"Practice saying ''no'' without guilt","ru":"Учиться говорить «нет» без вины","es":"Practicar decir «no» sin culpa"}},{"id":"pause","label":{"en":"Allow time to decide","ru":"Давать время на решение","es":"Dar tiempo para decidir"}},{"id":"listen","label":{"en":"Listen without persuading","ru":"Слушать без уговоров","es":"Escuchar sin presionar"}},{"id":"unsure","label":{"en":"I need more clarity","ru":"Нужна ясность","es":"Necesito más claridad"}}]'::jsonb),
('tantric_dialogue_answers_v1','[{"id":"share","label":{"en":"Share a personal preference","ru":"Рассказать о своём предпочтении","es":"Compartir una preferencia"}},{"id":"ask","label":{"en":"Ask what the other person wants","ru":"Спросить о желаниях другого","es":"Preguntar qué desea la otra persona"}},{"id":"limits","label":{"en":"Discuss comfort and limits","ru":"Обсудить комфорт и границы","es":"Hablar sobre comodidad y límites"}},{"id":"listen","label":{"en":"Listen without interrupting","ru":"Выслушать без перебиваний","es":"Escuchar sin interrumpir"}},{"id":"timing","label":{"en":"Choose a calm moment","ru":"Выбрать спокойный момент","es":"Elegir un momento tranquilo"}},{"id":"pause","label":{"en":"Not ready to talk yet","ru":"Пока не готов(а) к разговору","es":"Aún no quiero hablar"}}]'::jsonb),
('tantric_step_answers_v1','[{"id":"journal","label":{"en":"Note my feelings privately","ru":"Лично записать ощущения","es":"Anotar mis sensaciones en privado"}},{"id":"prepare","label":{"en":"Prepare one respectful sentence","ru":"Подготовить одну уважительную фразу","es":"Preparar una frase respetuosa"}},{"id":"conversation","label":{"en":"Invite a no-pressure conversation","ru":"Предложить разговор без давления","es":"Proponer una conversación sin presión"}},{"id":"notice","label":{"en":"Notice comfort and limits","ru":"Замечать комфорт и границы","es":"Observar comodidad y límites"}},{"id":"learn","label":{"en":"Find reliable education or support","ru":"Найти надёжное обучение или поддержку","es":"Buscar información o apoyo fiable"}},{"id":"pause","label":{"en":"Pause and do nothing for now","ru":"Пока сделать паузу","es":"Pausar y no hacer nada por ahora"}}]'::jsonb),
('tantric_review_answers_v1','[{"id":"clarity","label":{"en":"More clarity about my desires","ru":"Ясность относительно желаний","es":"Más claridad sobre mis deseos"}},{"id":"boundary","label":{"en":"A boundary worth honoring","ru":"Границу, которую стоит уважать","es":"Un límite que merece respeto"}},{"id":"sentence","label":{"en":"A kind, direct sentence","ru":"Мягкую, ясную фразу","es":"Una frase amable y clara"}},{"id":"acceptance","label":{"en":"Acceptance of my own pace","ru":"Принятие своего темпа","es":"Aceptación de mi propio ritmo"}},{"id":"choice","label":{"en":"Freedom to choose","ru":"Свободу выбирать","es":"Libertad de elegir"}},{"id":"pause","label":{"en":"Permission to pause","ru":"Разрешение на паузу","es":"Permiso para pausar"}}]'::jsonb)
INSERT INTO app_private.coaching_steps (model_key,step_key,model_order,title_i18n,emphasis_i18n,key_question_i18n) VALUES
('tantric_intimacy_v1','intention',1,'{"en":"Choose your focus","ru":"Выберите тему","es":"Elige tu enfoque"}'::jsonb,'{"en":"You decide what is safe and relevant to explore.","ru":"Вы сами выбираете безопасную и подходящую тему.","es":"Tú decides qué es seguro y relevante explorar."}'::jsonb,'{"en":"You may skip any question. No details of sexual acts are needed.","ru":"Любой вопрос можно пропустить. Подробности интимных действий не нужны.","es":"Puedes omitir cualquier pregunta. No se requieren detalles sexuales."}'::jsonb),
('tantric_intimacy_v1','presence',2,'{"en":"Body awareness","ru":"Телесное присутствие","es":"Conciencia corporal"}'::jsonb,'{"en":"Notice sensations without trying to change them.","ru":"Замечайте ощущения, не пытаясь их изменить.","es":"Observa las sensaciones sin intentar cambiarlas."}'::jsonb,'{"en":"No touching, undressing, breath-holding or physical practice is required.","ru":"Прикосновения, обнажение и телесные упражнения не нужны.","es":"No se requiere contacto físico, desnudez ni ejercicios corporales."}'::jsonb),
('tantric_intimacy_v1','desire',3,'{"en":"Your own desires","ru":"Ваши желания","es":"Tus propios deseos"}'::jsonb,'{"en":"Desire is personal, variable and never an obligation.","ru":"Желание индивидуально, меняется и никогда не является обязанностью.","es":"El deseo es personal, cambiante y nunca una obligación."}'::jsonb,'{"en":"Different people want different forms of closeness; no preference is scored.","ru":"Людям подходят разные формы близости — правильного ответа нет.","es":"Cada persona prefiere distintas formas de cercanía; no se puntúa ninguna."}'::jsonb),
('tantric_intimacy_v1','boundaries',4,'{"en":"Personal boundaries","ru":"Личные границы","es":"Límites personales"}'::jsonb,'{"en":"A boundary can change; a pause or no must be respected.","ru":"Границы могут меняться; пауза и «нет» должны уважаться.","es":"Los límites pueden cambiar; hay que respetar una pausa o un no."}'::jsonb,'{"en":"You never have to agree to closeness to please someone.","ru":"Не нужно соглашаться на близость ради чьего-либо одобрения.","es":"No tienes que aceptar intimidad para complacer a nadie."}'::jsonb),
('tantric_intimacy_v1','consent',5,'{"en":"Clear, ongoing consent","ru":"Ясное согласие","es":"Consentimiento continuo"}'::jsonb,'{"en":"A yes is specific and reversible; silence is not consent.","ru":"Согласие конкретно и его можно отозвать; молчание — не согласие.","es":"El sí es específico y reversible; el silencio no es consentimiento."}'::jsonb,'{"en":"Nobody owes an explanation for saying no.","ru":"Никто не обязан объяснять своё «нет».","es":"Nadie debe justificar un no."}'::jsonb),
('tantric_intimacy_v1','dialogue',6,'{"en":"Mutual dialogue","ru":"Взаимный диалог","es":"Diálogo mutuo"}'::jsonb,'{"en":"You can ask; the other person has the same right to choose.","ru":"Вы можете просить; другой человек тоже вправе выбирать.","es":"Puedes pedir; la otra persona también tiene derecho a elegir."}'::jsonb,'{"en":"Choose a respectful conversation, not a technique to persuade someone.","ru":"Выберите уважительный разговор, а не способ кого-то уговорить.","es":"Elige el diálogo respetuoso, no una técnica para convencer."}'::jsonb),
('tantric_intimacy_v1','step',7,'{"en":"A pressure-free step","ru":"Шаг без давления","es":"Un paso sin presión"}'::jsonb,'{"en":"Choose only a small, reversible action under your control.","ru":"Выберите небольшой обратимый шаг, зависящий только от вас.","es":"Elige un paso pequeño y reversible que dependa de ti."}'::jsonb,'{"en":"You can choose rest or no action. Never make intimacy a performance goal.","ru":"Можно выбрать отдых или ничего не делать. Близость — не норматив.","es":"Puedes descansar o no actuar. La intimidad no es una meta de rendimiento."}'::jsonb),
('tantric_intimacy_v1','review',8,'{"en":"Your reflection","ru":"Ваш вывод","es":"Tu reflexión"}'::jsonb,'{"en":"Keep only insights you personally agree with.","ru":"Оставьте лишь выводы, с которыми вы согласны.","es":"Conserva solo lo que resuene contigo."}'::jsonb,'{"en":"This is a personal reflection, not a sexual health assessment.","ru":"Это личное размышление, не оценка сексуального здоровья.","es":"Es una reflexión personal, no una evaluación de salud sexual."}'::jsonb)
INSERT INTO app_private.coaching_questions (question_key,model_key,step_key,position,prompt_i18n,answer_type,answer_set_key,core,required,interaction_note) VALUES
('tantric_intention_q1_v1','tantric_intimacy_v1','intention',1,'{"en":"What aspect of intimacy matters most to you right now?","ru":"Какая тема интимной жизни сейчас важнее для вас?","es":"¿Qué aspecto de tu intimidad te importa más ahora?"}'::jsonb,'single_choice','tantric_intention_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.'),
('tantric_presence_q1_v1','tantric_intimacy_v1','presence',1,'{"en":"How do you usually recognize comfort or discomfort in closeness?","ru":"Как вы обычно распознаёте комфорт или дискомфорт в близости?","es":"¿Cómo reconoces la comodidad o la incomodidad en la intimidad?"}'::jsonb,'single_choice','tantric_presence_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.'),
('tantric_desire_q1_v1','tantric_intimacy_v1','desire',1,'{"en":"What kind of closeness would feel genuinely welcome to you?","ru":"Какую форму близости вам действительно хотелось бы выбрать?","es":"¿Qué tipo de cercanía te resultaría realmente bienvenida?"}'::jsonb,'single_choice','tantric_desire_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.'),
('tantric_boundaries_q1_v1','tantric_intimacy_v1','boundaries',1,'{"en":"Which boundary would help you feel safer and freer to choose?","ru":"Какая граница поможет чувствовать себя спокойнее и свободнее в выборе?","es":"¿Qué límite te ayudaría a elegir con más tranquilidad y libertad?"}'::jsonb,'single_choice','tantric_boundaries_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.'),
('tantric_consent_q1_v1','tantric_intimacy_v1','consent',1,'{"en":"What would make conversations about consent easier for you?","ru":"Что помогло бы проще разговаривать о согласии?","es":"¿Qué facilitaría hablar sobre el consentimiento?"}'::jsonb,'single_choice','tantric_consent_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.'),
('tantric_dialogue_q1_v1','tantric_intimacy_v1','dialogue',1,'{"en":"What conversation could strengthen mutual respect and closeness?","ru":"Какой разговор поможет укрепить взаимное уважение и близость?","es":"¿Qué conversación fortalecería el respeto y la cercanía mutuos?"}'::jsonb,'single_choice','tantric_dialogue_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.'),
('tantric_step_q1_v1','tantric_intimacy_v1','step',1,'{"en":"What gentle next step, if any, would you like to choose?","ru":"Какой бережный следующий шаг, если он нужен, вы хотите выбрать?","es":"¿Qué pequeño paso, si lo deseas, te gustaría elegir?"}'::jsonb,'single_choice','tantric_step_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.'),
('tantric_review_q1_v1','tantric_intimacy_v1','review',1,'{"en":"What would you most like to take away from this conversation?","ru":"Что самое важное вы хотите унести из этой сессии?","es":"¿Qué te gustaría conservar de esta conversación?"}'::jsonb,'single_choice','tantric_review_answers_v1',true,false,'Adult-only opt-in, safe to skip. No explicit sexual descriptions or bodywork required.')
